const DAYS=['Every day','Every Monday','Every Tuesday','Every Wednesday','Every Thursday','Every Friday','Every Saturday','Every Sunday','Any day'];
let chores=[],members=[],revs={};
const $=id=>document.getElementById(id);
function say(t,k){const m=$('msg');m.textContent=t;m.className=k||'';}
function fill(sel,vals,keep){const cur=keep?sel.value:'';sel.textContent='';for(const v of vals){const o=document.createElement('option');o.value=v;o.textContent=v;sel.appendChild(o);}if(cur&&vals.includes(cur))sel.value=cur;}
function render(){
fill($('who'),members.length?members:['Me'],true);
const ul=$('list');ul.textContent='';
$('empty').hidden=chores.length>0;
for(const c of chores){
const li=document.createElement('li');li.setAttribute('data-hook','item');if(c.done)li.className='done';
const cb=document.createElement('input');cb.type='checkbox';cb.checked=!!c.done;cb.setAttribute('aria-label','Done: '+c.name);
cb.addEventListener('change',()=>toggle(c.id,cb.checked));
const t=document.createElement('span');t.className='txt';
const n=document.createElement('span');n.className='nm';n.textContent=c.name;
const m=document.createElement('span');m.className='meta';m.textContent=c.assignee+' · '+c.day+(c.done?' · done':'');
t.appendChild(n);t.appendChild(m);
const b=document.createElement('button');b.type='button';b.className='remove';b.setAttribute('data-hook','item-remove');b.textContent='Remove';b.setAttribute('aria-label','Remove '+c.name);
b.addEventListener('click',()=>remove(c.id));
li.appendChild(cb);li.appendChild(t);li.appendChild(b);ul.appendChild(li);}
}
async function load(){
const r=await tessera.call('data.read',{});
chores=r.data.chores||[];members=(r.data.members||[]).map(x=>x.name);revs=r.revisions.chores||{};render();}
async function patch(ops,okMsg){
try{await tessera.call('data.patch',{operations:ops});await load();say(okMsg,'ok');return true;}
catch(e){say('That did not work and nothing was changed. Please try again.','err');return false;}}
async function add(){
const name=$('name').value.trim();
if(!name){say('Type the chore first.','err');$('name').focus();return;}
const ok=await patch([{op:'add',collection:'chores',record:{name:name,assignee:$('who').value,day:$('day').value,done:false}}],'Added “'+name+'”.');
if(ok){$('name').value='';$('name').focus();}}
function toggle(id,v){patch([{op:'replace',collection:'chores',id:id,revisionCount:revs[id],fields:{done:v}}],v?'Marked done.':'Marked not done.');}
function remove(id){const c=chores.find(x=>x.id===id);patch([{op:'remove',collection:'chores',id:id,revisionCount:revs[id]}],'Removed “'+(c?c.name:'chore')+'”.');}
function reset(){const ops=chores.filter(c=>c.done).map(c=>({op:'replace',collection:'chores',id:c.id,revisionCount:revs[c.id],fields:{done:false}}));
if(!ops.length){say('No ticks to clear.');return;}patch(ops,'All ticks cleared.');}
$('add').addEventListener('click',add);
$('name').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();add();}});
$('reset').addEventListener('click',reset);
fill($('day'),DAYS);
load().catch(()=>say('Could not load the chores.','err'));
